/** Every vendored glyph, keyed by the name call sites use. */
export const ICONS = {
  SearchOutline: SearchOutlineIcon,
  EllipsisOutline: EllipsisOutlineIcon,
  PlusOutlineMedium: PlusOutlineMediumIcon,
  CloseOutline: CloseOutlineIcon,
  CheckOutline: CheckOutlineIcon,
  ChevronDownOutline: ChevronDownOutlineIcon,
  ChevronUpOutline: ChevronUpOutlineIcon,
  ChevronLeftOutline: ChevronLeftOutlineIcon,
  ChevronRightOutline: ChevronRightOutlineIcon,
  CopyOutline: CopyOutlineIcon,
  BranchOutline: BranchOutlineIcon,
  LikeOutline: LikeOutlineIcon,
  LikeFill: LikeFillIcon,
  DislikeOutline: DislikeOutlineIcon,
  DislikeFill: DislikeFillIcon,
  DatabaseOutline: DatabaseOutlineIcon,
  GaugeOutline: GaugeOutlineIcon,
  ThinkOutline: ThinkOutlineIcon,
  BrowseOutline: BrowseOutlineIcon,
  EditOutline: EditOutlineIcon,
  CodeOutline: CodeOutlineIcon,
  ApiOutline: ApiOutlineIcon,
  SparkleRegular: SparkleRegularIcon,
  ChecklistOutline: ChecklistOutlineIcon,
  PlayOutline: PlayOutlineIcon,
  QuestionOutline: QuestionOutlineIcon,
  PlanOutline: PlanOutlineIcon,
  GoalOutline: GoalOutlineIcon,
  QueueOutline: QueueOutlineIcon,
  TrashOutline: TrashOutlineIcon,
  SendOutline: SendOutlineIcon,
  WarningOutline: WarningOutlineIcon,
  RefreshOutline: RefreshOutlineIcon,
  ContextInjectionOutline: ContextInjectionOutlineIcon,
  ShareOutline: ShareOutlineIcon,
  SettingsOutline: SettingsOutlineIcon,
  SendSolid: SendSolidIcon,
  StopSolid: StopSolidIcon,
} as const

export type IconName = keyof typeof ICONS

/**
 * Draw one vendored product icon.
 * @param props.name - which glyph.
 * @param props.size - square edge in px; defaults to the web's own drawn size.
 * @param props.color - the color `currentColor` resolves to.
 * @param props.style - optional layout style (margins, alignment) for the svg.
 * @returns the glyph element.
 */
export function Icon({ name, size, color, style }: {
  name: IconName
  size?: number
  color: string
  style?: StyleProp<ViewStyle>
}): React.JSX.Element {
  const Glyph = ICONS[name]
  return (
    <Glyph
      color={color}
      {...(size === undefined ? {} : { size })}
      {...(style === undefined ? {} : { style })}
    />
  )
}
